input.command:
node -e "
const fs = require('fs');
const data = JSON.parse(fs.readFileSync('E:/kaifa/英雄排行/MOBA游戏梯度/曙光英雄/曙光英雄.json', 'utf8'));

const updated = data.map(hero => {
  const cp = parseInt(hero.combatPower) || 0;
  const guo9 = Math.round(cp * 0.40);
  const guo50 = Math.round(cp * 0.35);
  const guo100 = cp - guo9 - guo50; // remainder ensures exact sum

  return {
    heroName: hero.heroName,
    appearanceRank: hero.appearanceRank,
    '国9战力': guo9,
    '国50战力': guo50,
    '国100战力': guo100,
    combatPower: guo9 + guo50 + guo100, // computed = sum of three
    winRate: hero.winRate
  };
});

// verify
let errors = updated.filter(h => h.combatPower !== (h['国9战力'] + h['国50战力'] + h['国100战力']));
console.log('Errors:', errors.length);
console.log('First 3:', JSON.stringify(updated.slice(0,3), null, 2));
console.log('Total heroes:', updated.length);

fs.writeFileSync('E:/kaifa/英雄排行/MOBA游戏梯度/曙光英雄/曙光英雄.json', JSON.stringify(updated, null, 2), 'utf8');
console.log('Done');
"

