121	  th.sort-asc .sort-arrow,
122	  th.sort-desc .sort-arrow { opacity: 1; color: var(--accent); }
123	  th.col-index { width: 48px; min-width: 48px; text-align: center; cursor: default; color: var(--text-muted); }
