188	    animation: toastIn .25s ease;
189	    box-shadow: 0 4px 12px rgba(0,0,0,.4);
190	  }
191	  @keyframes toastIn { from { opacity:0; transform:translateX(-50%) translateY(8px); } }
192	
193	  /* ── stats bar ── */
194	  .stats {
195	    background: var(--surface);
196	    border-bottom: 1px solid var(--border);
197	    padding: 6px 24px;
