200	    display: flex;
201	    gap: 16px;
202	    flex-wrap: wrap;
203	    align-items: center;
204	  }
205	  .stats .dirty { color: var(--warning); }
206	</style>
207	</head>
208	<body>
209	
210	<div class="header">
211	  <h1>📊 JSON 数据编辑器</h1>
212	  <div class="sep"></div>
213	  <div class="toolbar">
214	    <span class="file-label">
215	      📂 打开 JSON
216	      <input type="file" id="fileInput" accept=".json" onchange="loadFile(this)">
217	    </span>
218	    <select id="presetSelect" onchange="loadPreset(this.value)">
219	      <option value="">— 快速加载项目数据 —</option>
220	      <optgroup label="LoLM 分路数据">
221	        <option value="lolm/上路.json">上路</option>
222	        <option value="lolm/打野.json">打野</option>
223	        <option value="lolm/中路.json">中路</option>
224	        <option value="lolm/下路.json">下路</option>
225	        <option value="lolm/辅助.json">辅助</option>
226	      </optgroup>
227	      <optgroup label="曙光英雄">
228	        <option value="曙光英雄/曙光英雄.json">曙光英雄</option>
229	      </optgroup>
230	    </select>
231	    <button onclick="addRow()" disabled id="addBtn">＋ 添加行</button>
232	    <button onclick="undoAll()" disabled id="undoBtn" class="danger" style="display:none">↩ 撤销全部修改</button>
233	  </div>
234	  <div class="toolbar">
235	    <button class="primary" onclick="saveJSON()" disabled id="saveBtn">💾 下载 JSON</button>
236	  </div>
237	</div>
238	
239	<div class="stats" id="stats" style="display:none">
240	  <span id="statFile"></span>
241	  <span id="statRows"></span>
242	  <span id="statDirty" class="dirty"></span>
243	</div>
244	
245	<div class="table-wrap" id="tableWrap">
246	  <div class="empty" id="empty">
247	    <div class="icon">📂</div>
248	    <p>打开一个 JSON 文件开始编辑</p>
249	    <p style="font-size:12px;margin-top:4px;">支持从上方菜单加载项目数据，或拖放 / 选择本地 .json 文件</p>
250	  </div>
251	  <table id="dataTable" style="display:none">
252	    <thead id="tableHead"></thead>
253	    <tbody id="tableBody"></tbody>
254	  </table>
255	</div>
256	
257	<script>
258	// ── state ──
259	let data = null;           // parsed array of objects
260	let columns = [];          // detected column keys
261	let original = null;       // deep copy for undo
262	let sortKey = null;
263	let sortDir = 1;           // 1=asc, -1=desc
264	let currentFile = '';
265	
266	// ── helpers ──
267	function $(id) { return document.getElementById(id); }
268	
269	function toast(msg) {
270	  const el = Object.assign(document.createElement('div'), {className:'toast', textContent:msg});
271	  document.body.appendChild(el);
272	  setTimeout(() => el.remove(), 2000);
273	}
274	
275	function detectColumns(arr) {
276	  if (!arr || !arr.length) return [];
277	  const keys = new Set();
278	  arr.forEach(obj => Object.keys(obj).forEach(k => keys.add(k)));
279	  return Array.from(keys);
280	}
281	
282	function normalizeValue(val) {
283	  if (val === null || val === undefined) return '';
284	  if (typeof val === 'object') return JSON.stringify(val);
285	  return String(val);
286	}
287	
288	// ── render ──
289	function render() {
290	  if (!data || !data.length) {
291	    $('tableWrap').querySelector('table').style.display = 'none';
292	    $('empty').style.display = '';
293	    $('stats').style.display = 'none';
294	    $('saveBtn').disabled = true;
295	    $('addBtn').disabled = true;
296	    return;
297	  }
298	
299	  $('empty').style.display = 'none';
300	  $('dataTable').style.display = '';
301	  $('saveBtn').disabled = false;
302	  $('addBtn').disabled = false;
303	  $('stats').style.display = 'flex';
304	
305	  columns = detectColumns(data);
306	
307	  // sort
308	  let sorted = [...data];
309	  if (sortKey && columns.includes(sortKey)) {
310	    sorted.sort((a, b) => {
311	      let va = a[sortKey], vb = b[sortKey];
312	      // try numeric
313	      let na = parseFloat(va), nb = parseFloat(vb);
314	      if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
315	      return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
316	    });
317	  }
318	
319	  // head
320	  let headHtml = '<tr><th class="col-index">#</th>';
321	  columns.forEach(col => {
322	    let cls = '';
323	    if (sortKey === col) cls = sortDir === 1 ? 'sort-asc' : 'sort-desc';
324	    headHtml += `<th class="${cls}" onclick="sortBy('${col.replace(/'/g, "\\'")}')">${col}<span class="sort-arrow">${sortKey===col ? (sortDir===1 ? '▲' : '▼') : ''}</span></th>`;
325	  });
326	  headHtml += '<th class="col-index" style="cursor:default">✕</th></tr>';
327	  $('tableHead').innerHTML = headHtml;
328	
329	  // body
330	  let bodyHtml = '';
331	  sorted.forEach((row, i) => {
332	    bodyHtml += `<tr>`;
333	    bodyHtml += `<td class="col-index">${i + 1}</td>`;
334	    columns.forEach(col => {
335	      let val = normalizeValue(row[col]);
336	      let isMod = original && JSON.stringify(row) !== JSON.stringify(original[data.indexOf(row)]);
337	      bodyHtml += `<td class="editable${isMod ? ' modified' : ''}" onclick="startEdit(this, ${i}, '${col.replace(/'/g, "\\'")}')"><input value="${val.replace(/"/g, '&quot;')}" data-col="${col.replace(/'/g, "\\'")}" data-row="${i}" onchange="commitEdit(this)" onblur="commitEdit(this)" onfocus="this.select()"></td>`;
338	    });
339	    bodyHtml += `<td><button class="del-btn" onclick="deleteRow(${i})" title="删除此行">✕</button></td>`;
340	    bodyHtml += `</tr>`;
341	  });
342	  $('tableBody').innerHTML = bodyHtml;
343	
344	  // stats
345	  $('statFile').textContent = '📄 ' + (currentFile || '未命名数据');
346	  $('statRows').textContent = `📋 ${data.length} 行 × ${columns.length} 列`;
347	
348	  let dirtyCount = countDirty();
349	  if (dirtyCount > 0) {
350	    $('statDirty').textContent = `⚠ 已修改 ${dirtyCount} 个字段`;
351	    $('undoBtn').style.display = '';
352	    $('undoBtn').disabled = false;
353	  } else {
354	    $('statDirty').textContent = '';
355	    $('undoBtn').style.display = 'none';
356	  }
357	}
358	
359	function countDirty() {
360	  if (!original) return 0;
361	  let count = 0;
362	  data.forEach((row, i) => {
363	    if (i >= original.length) { count += Object.keys(row).length; return; }
364	    columns.forEach(col => {
365	      if (String(row[col] ?? '') !== String(original[i][col] ?? '')) count++;
366	    });
367	  });
368	  return count;
369	}
370	
371	// ── edit ──
372	function startEdit(td, rowIdx, col) {
373	  const input = td.querySelector('input');
374	  if (!input || document.activeElement === input) return;
375	  input.focus();
376	}
377	
378	function commitEdit(input) {
379	  const col = input.dataset.col;
380	  const rowIdx = parseInt(input.dataset.row);
381	  let val = input.value.trim();
382	
383	  // auto-detect number
384	  if (val !== '' && !isNaN(val) && !/^0\d/.test(val)) {
385	    val = Number(val);
386	  }
387	
388	  if (!original) original = JSON.parse(JSON.stringify(data));
389	
390	  // find correct row index in unsorted data
391	  const sorted = getSortedData();
392	  const row = sorted[rowIdx];
393	  // find same object in data
394	  const dataIdx = data.indexOf(row);
395	  if (dataIdx >= 0) {
396	    data[dataIdx][col] = val;
397	  }
398	
399	  render();
400	}
401	
402	// ── sort ──
403	function getSortedData() {
404	  if (!data) return [];
405	  let sorted = [...data];
406	  if (sortKey && columns.includes(sortKey)) {
407	    sorted.sort((a, b) => {
408	      let va = a[sortKey], vb = b[sortKey];
409	      let na = parseFloat(va), nb = parseFloat(vb);
410	      if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
411	      return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
412	    });
413	  }
414	  return sorted;
415	}
416	
417	function sortBy(col) {
418	  if (sortKey === col) {
419	    sortDir *= -1;
420	  } else {
421	    sortKey = col;
422	    sortDir = 1;
423	  }
424	  render();
425	}
426	
427	// ── row operations ──
428	function addRow() {
429	  if (!data) return;
430	  if (!original) original = JSON.parse(JSON.stringify(data));
431	  const newRow = {};
432	  columns.forEach(col => { newRow[col] = ''; });
433	  data.push(newRow);
434	  render();
435	  // scroll to bottom
436	  $('tableWrap').scrollTop = $('tableWrap').scrollHeight;
437	  toast('已添加新行');
438	}
439	
440	function deleteRow(sortedIdx) {
441	  const sorted = getSortedData();
442	  const row = sorted[sortedIdx];
443	  const dataIdx = data.indexOf(row);
444	  if (dataIdx < 0) return;
445	  if (!original) original = JSON.parse(JSON.stringify(data));
446	  const name = row[columns[0]] || `第${dataIdx+1}行`;
447	  if (!confirm(`确定要删除 "${name}" 吗？`)) return;
448	  data.splice(dataIdx, 1);
449	  render();
450	  toast(`已删除: ${name}`);
451	}
452	
453	// ── undo ──
454	function undoAll() {
455	  if (!original) return;
456	  if (!confirm('确定撤销所有修改，恢复到加载时的原始数据吗？此操作不可撤销。')) return;
457	  data = JSON.parse(JSON.stringify(original));
458	  original = null;
459	  sortKey = null;
460	  sortDir = 1;
461	  render();
462	  toast('已恢复到原始数据');
463	}
464	
465	// ── load JSON ──
466	function setData(arr, filename) {
467	  if (!Array.isArray(arr)) {
468	    // try to find an array inside
469	    const found = Object.values(arr).find(v => Array.isArray(v));
470	    if (found) arr = found;
471	    else {
472	      alert('JSON 文件格式不正确：需要包含一个数组，或包含数组的对象。');
473	      return;
474	    }
475	  }
476	  data = arr.map(row => {
477	    // clone and normalize values
478	    const clone = {};
479	    Object.keys(row).forEach(k => {
480	      let v = row[k];
481	      if (typeof v === 'string' && v.endsWith('%') && !isNaN(parseFloat(v))) {
482	        // keep as string for editing consistency
483	        clone[k] = v;
484	      } else {
485	        clone[k] = v;
486	      }
487	    });
488	    return clone;
489	  });
490	  original = null;
491	  sortKey = null;
492	  sortDir = 1;
493	  currentFile = filename || '';
494	  render();
495	  toast(`已加载: ${filename || '数据'} (${data.length} 行)`);
496	}
497	
498	function loadFile(input) {
499	  const file = input.files[0];
500	  if (!file) return;
501	  currentFile = file.name;
502	  const reader = new FileReader();
503	  reader.onload = () => {
504	    try {
505	      const parsed = JSON.parse(reader.result);
506	      setData(parsed, file.name);
507	    } catch (e) {
508	      alert('JSON 解析失败: ' + e.message);
509	    }
510	  };
511	  reader.readAsText(file);
512	  input.value = '';
513	}
514	
515	function loadPreset(path) {
516	  if (!path) return;
517	  $('presetSelect').value = '';
518	  fetch(path)
519	    .then(r => { if (!r.ok) throw new Error(r.status + ' ' + r.statusText); return r.json(); })
520	    .then(json => {
521	      currentFile = path.split('/').pop();
522	      setData(json, currentFile);
523	    })
524	    .catch(err => alert('加载失败: ' + err.message));
525	}
526	
527	// ── save ──
528	function saveJSON() {
529	  if (!data) return;
530	  const json = JSON.stringify(data, null, 2);
531	  const blob = new Blob([json], {type: 'application/json'});
532	  const url = URL.createObjectURL(blob);
533	  const a = Object.assign(document.createElement('a'), {
534	    href: url,
535	    download: currentFile || 'data.json'
536	  });
537	  a.click();
538	  URL.revokeObjectURL(url);
539	  toast('JSON 已下载');
540	}
541	
542	// ── keyboard shortcuts ──
543	document.addEventListener('keydown', e => {
544	  if ((e.ctrlKey || e.metaKey) && e.key === 's') {
545	    e.preventDefault();
546	    saveJSON();
547	  }
548	  if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
549	    e.preventDefault();
550	    undoAll();
551	  }
552	});
553	
554	// ── drag & drop ──
555	document.body.addEventListener('dragover', e => { e.preventDefault(); });
556	document.body.addEventListener('drop', e => {
557	  e.preventDefault();
558	  const file = e.dataTransfer.files[0];
559	  if (file && file.name.endsWith('.json')) {
560	    currentFile = file.name;
561	    const reader = new FileReader();
562	    reader.onload = () => {
563	      try { setData(JSON.parse(reader.result), file.name); }
564	      catch (err) { alert('JSON 解析失败: ' + err.message); }
565	    };
566	    reader.readAsText(file);
567	  }
568	});
569	</script>
570	</body>
571	</html>
