206	</style>
207	</head>
208	<body>
209	
210	<div class="header">
211	  <h1>📊 JSON 数据编辑器</h1>
212	  <div class="sep"></div>
213	  <div class="toolbar">
214	    <span class="file-label">
215	      📂 打开 JSON
216	      <input type="file" id="fileInput" accept=".json" onchange="loadFile(this)">
217	    </span>
218	    <select id="presetSelect" onchange="loadPreset(this.value)">
219	      <option value="">— 快速加载项目数据 —</option>
220	      <optgroup label="LoLM 分路数据">
221	        <option value="lolm/上路.json">上路</option>
222	        <option value="lolm/打野.json">打野</option>
223	        <option value="lolm/中路.json">中路</option>
224	        <option value="lolm/下路.json">下路</option>
225	        <option value="lolm/辅助.json">辅助</option>
226	      </optgroup>
227	      <optgroup label="曙光英雄">
228	        <option value="曙光英雄/曙光英雄.json">曙光英雄</option>
229	      </optgroup>
230	    </select>
231	    <button onclick="addRow()" disabled id="addBtn">＋ 添加行</button>
232	    <button onclick="undoAll()" disabled id="undoBtn" class="danger" style="display:none">↩ 撤销全部修改</button>
233	  </div>
234	  <div class="toolbar">
235	    <button class="primary" onclick="saveJSON()" disabled id="saveBtn">💾 下载 JSON</button>
236	  </div>
237	</div>
238	
239	<div class="stats" id="stats" style="display:none">
240	  <span id="statFile"></span>
241	  <span id="statRows"></span>
242	  <span id="statDirty" class="dirty"></span>
243	  <span id="statComputed" class="computed-info"></span>
244	</div>
245	
246	<div class="table-wrap" id="tableWrap">
247	  <div class="empty" id="empty">
248	    <div class="icon">📂</div>
249	    <p>打开一个 JSON 文件开始编辑</p>
250	    <p style="font-size:12px;margin-top:4px;">支持从上方菜单加载项目数据，或拖放 / 选择本地 .json 文件</p>
251	  </div>
252	  <table id="dataTable" style="display:none">
253	    <thead id="tableHead"></thead>
254	    <tbody id="tableBody"></tbody>
255	  </table>
256	</div>
257	
258	<script>
259	// ── state ──
260	let data = null;           // parsed array of objects
261	let columns = [];          // detected column keys
262	let original = null;       // deep copy for undo
263	let sortKey = null;
264	let sortDir = 1;
265	let currentFile = '';
266	let computedFields = {};   // { fieldName: { dependsOn: [], compute: fn } }
267	
268	// ── computed field definitions ──
269	// Add more definitions here when needed. The editor auto-detects which ones
270	// apply based on whether all dependsOn columns exist in the loaded data.
271	const COMPUTED_DEFS = {
272	  combatPower: {
273	    dependsOn: ['国9战力', '国50战力', '国100战力'],
274	    compute: (row) => (Number(row['国9战力']) || 0) + (Number(row['国50战力']) || 0) + (Number(row['国100战力']) || 0),
275	    hint: '= 国9 + 国50 + 国100'
276	  }
277	};
278	
279	// ── helpers ──
280	function $(id) { return document.getElementById(id); }
281	
282	function toast(msg) {
283	  const el = Object.assign(document.createElement('div'), {className:'toast', textContent:msg});
284	  document.body.appendChild(el);
285	  setTimeout(() => el.remove(), 2000);
286	}
287	
288	function detectColumns(arr) {
289	  if (!arr || !arr.length) return [];
290	  const keys = new Set();
291	  arr.forEach(obj => Object.keys(obj).forEach(k => keys.add(k)));
292	  return Array.from(keys);
293	}
294	
295	function normalizeValue(val) {
296	  if (val === null || val === undefined) return '';
297	  if (typeof val === 'object') return JSON.stringify(val);
298	  return String(val);
299	}
300	
301	// Check which computed fields apply to the current data
302	function resolveComputedFields() {
303	  computedFields = {};
304	  if (!data || !data.length) return;
305	  const cols = new Set(detectColumns(data));
306	  for (const [field, def] of Object.entries(COMPUTED_DEFS)) {
307	    if (cols.has(field) && def.dependsOn.every(d => cols.has(d))) {
308	      computedFields[field] = def;
309	    }
310	  }
311	}
312	
313	// ── render ──
314	function render() {
315	  resolveComputedFields();
316	
317	  if (!data || !data.length) {
318	    $('dataTable').style.display = 'none';
319	    $('empty').style.display = '';
320	    $('stats').style.display = 'none';
321	    $('saveBtn').disabled = true;
322	    $('addBtn').disabled = true;
323	    return;
324	  }
325	
326	  $('empty').style.display = 'none';
327	  $('dataTable').style.display = '';
328	  $('saveBtn').disabled = false;
329	  $('addBtn').disabled = false;
330	  $('stats').style.display = 'flex';
331	
332	  columns = detectColumns(data);
333	
334	  // sort
335	  let sorted = [...data];
336	  if (sortKey && columns.includes(sortKey)) {
337	    sorted.sort((a, b) => {
338	      let va = a[sortKey], vb = b[sortKey];
339	      let na = parseFloat(va), nb = parseFloat(vb);
340	      if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
341	      return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
342	    });
343	  }
344	
345	  // head
346	  let headHtml = '<tr><th class="col-index">#</th>';
347	  columns.forEach(col => {
348	    let cls = '';
349	    if (sortKey === col) cls = sortDir === 1 ? 'sort-asc' : 'sort-desc';
350	    if (computedFields[col]) cls += ' col-computed';
351	    const label = computedFields[col] ? col + ' 🔒' : col;
352	    headHtml += `<th class="${cls}" onclick="sortBy('${esc(col)}')">${label}<span class="sort-arrow">${sortKey===col ? (sortDir===1 ? '▲' : '▼') : ''}</span></th>`;
353	  });
354	  headHtml += '<th class="col-index" style="cursor:default">✕</th></tr>';
355	  $('tableHead').innerHTML = headHtml;
356	
357	  // body
358	  let bodyHtml = '';
359	  sorted.forEach((row, sortedIdx) => {
360	    const dataIdx = data.indexOf(row);
361	    bodyHtml += `<tr>`;
362	    bodyHtml += `<td class="col-index">${sortedIdx + 1}</td>`;
363	    columns.forEach(col => {
364	      if (computedFields[col]) {
365	        // ── computed cell (read-only) ──
366	        let val = normalizeValue(row[col]);
367	        bodyHtml += `<td class="computed" title="自动计算，不可编辑">${val}<span class="formula-hint">${computedFields[col].hint || ''}</span></td>`;
368	      } else {
