$('tableBody').addEventListener('keydown', function(e) {
  if (e.key === 'Tab') {
    const input = document.activeElement;
    if (!input || input.tagName !== 'INPUT' || !input.dataset.col) return;
    e.preventDefault();

    // Record target before commitEdit destroys the DOM
    const td = input.closest('td');
