    commitEdit(input);

    // Focus the next cell in the rebuilt DOM
    if (nextIdx >= 0) {
      const newCells = [...$('tableBody').querySelectorAll('td.editable')];
      if (nextIdx < newCells.length) startEdit(newCells[nextIdx]);
    }
  }

  // Enter on editable cell → move to cell below (same column, next row)
  if (e.key === 'Enter' && !e.shiftKey) {
    const input = document.activeElement;
    if (!input || input.tagName !== 'INPUT' || !input.dataset.col) return;
    e.preventDefault();

    const col = input.dataset.col;
