// Recalculate all computed fields for a single row
function recalcRow(row) {
  for (const [field, def] of Object.entries(computedFields)) {
    row[field] = def.compute(row);
  }
}

// Recalculate all computed fields for all rows (e.g. after initial load)
function recalcAll() {
  if (!data) return;
  resolveComputedFields();
  data.forEach(row => recalcRow(row));
}

// ── sort ──
function getSortedData() {
  if (!data) return [];
  let sorted = [...data];
  if (sortKey && columns.includes(sortKey)) {
    sorted.sort((a, b) => {
      let va = a[sortKey], vb = b[sortKey];
      let na = parseFloat(va), nb = parseFloat(vb);
      if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
      return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
    });
  }
  return sorted;
}

function sortBy(col) {
  if (computedFields[col]) return; // block sort on computed cols? No — allow it
  if (sortKey === col) {
    sortDir *= -1;
  } else {
    sortKey = col;
    sortDir = 1;
  }
  render();
}

// ── row operations ──
function addRow() {
  if (!data) return;
  if (!original) original = JSON.parse(JSON.stringify(data));
  const newRow = {};
  columns.forEach(col => {
    // computed fields start empty — will be recalc'd
    newRow[col] = computedFields[col] ? 0 : '';
  });
  data.push(newRow);
  recalcRow(newRow);
  render();
  $('tableWrap').scrollTop = $('tableWrap').scrollHeight;
  toast('已添加新行');
}

function deleteRow(sortedIdx) {
  const sorted = getSortedData();
  const row = sorted[sortedIdx];
  const dataIdx = data.indexOf(row);
  if (dataIdx < 0) return;
  if (!original) original = JSON.parse(JSON.stringify(data));
  const nameCol = columns.find(c => c.toLowerCase().includes('name') || c === 'heroName') || columns[0];
  const name = row[nameCol] || `第${dataIdx+1}行`;
  if (!confirm(`确定要删除 "${name}" 吗？`)) return;
  data.splice(dataIdx, 1);
  render();
  toast(`已删除: ${name}`);
}

// ── undo ──
function undoAll() {
  if (!original) return;
  if (!confirm('确定撤销所有修改，恢复到加载时的原始数据吗？此操作不可撤销。')) return;
  data = JSON.parse(JSON.stringify(original));
  original = null;
  sortKey = null;
  sortDir = 1;
  recalcAll();

