// ── Paste handler: multi-value paste from Excel ──
// When you copy a column from Excel, the clipboard contains newline-separated
// values. This handler detects that and fills downward from the focused cell.
$('tableBody').addEventListener('paste', function(e) {
  console.log('%c[PASTE EVENT] %cfired on tableBody', 'color:#58a6ff;font-weight:bold', 'color:#c9d1d9');

  const input = document.activeElement;
  console.log('  activeElement tagName:', input ? input.tagName : 'null',
    'has data-col:', input ? !!input.dataset.col : false,
    'col:', input ? input.dataset.col : 'N/A');

  if (!input || input.tagName !== 'INPUT' || !input.dataset.col) {
    console.log('  ⏭ skipped: not an editable input (tagName=' + (input ? input.tagName : 'null') + ')');
    return;
  }

  const pasteText = (e.clipboardData || window.clipboardData).getData('text');
  console.log('  pasteText length:', pasteText ? pasteText.length : 0);
  console.log('  pasteText preview:', pasteText ? pasteText.substring(0, 200).replace(/\n/g, '\\n').replace(/\t/g, '\\t') : '(empty)');

  if (!pasteText) {
    console.log('  ⏭ skipped: empty clipboard');
    return;
  }

  // Normalize line endings and split
  const rawLines = pasteText.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
  console.log('  rawLines count:', rawLines.length, 'after split');

  // Check for tabs too (Excel row copy)
  const hasTabs = pasteText.includes('\t');
  console.log('  hasTabs:', hasTabs);

  // Remove trailing empty lines (common when copying from Excel)
  while (rawLines.length && rawLines[rawLines.length - 1].trim() === '') rawLines.pop();
  console.log('  rawLines count after trim trailing empty:', rawLines.length);

  // If only one line AND no tabs, let the default paste behavior handle it
  if (rawLines.length <= 1 && !hasTabs) {
    console.log('  ⏭ skipped: single line, no tabs — using default paste');
    return;
  }

  // Multi-value paste detected — fill downward
  e.preventDefault();
  console.log('  ✅ multi-value paste triggered!');

