// ── undo ──
function undoAll() {
  if (!original) return;
  if (!confirm('确定撤销所有修改，恢复到加载时的原始数据吗？此操作不可撤销。')) return;
  data = JSON.parse(JSON.stringify(original));
  original = null;
  sortKey = null;
  sortDir = 1;
  recalcAll();
  render();
  toast('已恢复到原始数据');
}

// ── load JSON ──
function setData(arr, filename) {
  if (!Array.isArray(arr)) {
    const found = Object.values(arr).find(v => Array.isArray(v));
    if (found) arr = found;
    else {
      alert('JSON 文件格式不正确：需要包含一个数组，或包含数组的对象。');
      return;
    }
  }
  data = arr.map(row => {
    const clone = {};
    Object.keys(row).forEach(k => { clone[k] = row[k]; });
    return clone;
  });
  original = null;
  sortKey = null;
  sortDir = 1;
  currentFile = filename || '';

  // Apply computed field formulas to ensure consistency on load
  recalcAll();

  render();
  toast(`已加载: ${filename || '数据'} (${data.length} 行)`);
}

function loadFile(input) {
  const file = input.files[0];
  if (!file) return;
  currentFile = file.name;
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const parsed = JSON.parse(reader.result);
      setData(parsed, file.name);
    } catch (e) {
      alert('JSON 解析失败: ' + e.message);
    }
  };
  reader.readAsText(file);
  input.value = '';
}

function loadPreset(path) {
  if (!path) return;
  $('presetSelect').value = '';
  fetch(path)
    .then(r => { if (!r.ok) throw new Error(r.status + ' ' + r.statusText); return r.json(); })
    .then(json => {
      currentFile = path.split('/').pop();
      setData(json, currentFile);
    })
    .catch(err => alert('加载失败: ' + err.message));
}

// ── save ──
function saveJSON() {
  if (!data) return;

  // Final recalculation before saving to ensure all computed values are correct
  recalcAll();

  const json = JSON.stringify(data, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement('a'), {
    href: url,
    download: currentFile || 'data.json'
  });
  a.click();
  URL.revokeObjectURL(url);
  toast('JSON 已下载（含自动计算值）');
}

// ── keyboard shortcuts ──
document.addEventListener('keydown', e => {
  if ((e.ctrlKey || e.metaKey) && e.key === 's') {
    e.preventDefault();
    saveJSON();
  }
  if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
    e.preventDefault();
    undoAll();
  }
});

// ── drag & drop ──
document.body.addEventListener('dragover', e => { e.preventDefault(); });
document.body.addEventListener('drop', e => {
  e.preventDefault();
  const file = e.dataTransfer.files[0];
  if (file && file.name.endsWith('.json')) {
    currentFile = file.name;
    const reader = new FileReader();
    reader.onload = () => {
      try { setData(JSON.parse(reader.result), file.name); }
      catch (err) { alert('JSON 解析失败: ' + err.message); }
    };
    reader.readAsText(file);
  }
});

