// ── Paste handler: multi-value paste from Excel ──
// When you copy a column from Excel, the clipboard contains newline-separated
// values. This handler detects that and fills downward from the focused cell.
console.log('%c[INIT] %cPaste listener attached to tableBody', 'color:#3fb950;font-weight:bold', '');
$('tableBody').addEventListener('paste', function (e) {
  console.log('%c[PASTE] %cfired', 'color:#58a6ff;font-weight:bold', '');

  const input = document.activeElement;
  console.log('  activeEl:', input?.tagName || 'null', 'data-col:', input?.dataset?.col || 'none');

  if (!input || input.tagName !== 'INPUT' || !input.dataset.col) {
    console.log('  ⏭ skip: not editable input');
    return;
  }

  const pasteText = (e.clipboardData || window.clipboardData).getData('text');
  console.log('  pasteText len:', pasteText?.length || 0);

  if (!pasteText) {
    console.log('  ⏭ skip: empty clipboard');
    return;
  }

  // Normalize line endings and split
  const rawLines = pasteText.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
  const hasTabs = pasteText.includes('\t');
  console.log('  lines:', rawLines.length, 'hasTabs:', hasTabs);
  console.log('  preview:', pasteText.substring(0, 200).replace(/\n/g, '\\n').replace(/\t/g, '\\t'));

  // Remove trailing empty lines (common when copying from Excel)
  while (rawLines.length && rawLines[rawLines.length - 1].trim() === '') rawLines.pop();

  // If only one line and no tabs, let the default paste behavior handle it
  if (rawLines.length <= 1 && !hasTabs) {
    console.log('  ⏭ skip: single line, default paste');
    return;
  }

  // Multi-value paste detected — fill downward
  e.preventDefault();
  console.log('  ✅ multi-value paste!');

  const col = input.dataset.col;
  const sortedIdx = parseInt(input.dataset.sortedIdx);

  // Parse values, filtering empty lines
  const values = [];
  for (const line of rawLines) {
    const trimmed = line.trim();
    if (trimmed !== '') {
      if (!isNaN(trimmed) && !/^0\d/.test(trimmed)) {
        values.push(Number(trimmed));
      } else {
        values.push(trimmed);
      }
    }
  }

  if (!values.length) return;

  if (!original) original = JSON.parse(JSON.stringify(data));

  // ── DETAILED LOG ──
  console.group('%c📋 PASTE DEBUG %c' + values.length + ' values → column "' + col + '"',
    'font-weight:bold;color:#ffa940', 'color:#c9d1d9');
  console.log('Sort state:', { sortKey, sortDir: sortDir === 1 ? 'ASC' : 'DESC' });
  console.log('Paste starts at sortedIdx =', sortedIdx, '(screen row', sortedIdx + 1, ')');

  const sorted = getSortedData();

  // Print the sorted view summary (first 5 + last 2 rows)
  console.log('Sorted view (what you see on screen):');
  const nameCol = columns.find(c => c.toLowerCase().includes('name')) || columns[0];
  sorted.forEach((row, i) => {
    const marker = i === sortedIdx ? '◀── PASTE STARTS HERE' : '';
    if (i < 5 || i >= sorted.length - 2 || (i >= sortedIdx && i < sortedIdx + values.length)) {
      console.log(`  sorted[${i}] → data[${data.indexOf(row)}]  ${nameCol}=${row[nameCol]}  ${marker}`);
    } else if (i === 5) {
      console.log(`  ... (${sorted.length - 10} rows omitted) ...`);
    }
  });

  // Now do the actual paste with per-item logging
  console.log('Paste mapping:');
  const mappingTable = [];
  for (let i = 0; i < values.length; i++) {
    const targetSortedIdx = sortedIdx + i;

    if (targetSortedIdx < sorted.length) {
      const row = sorted[targetSortedIdx];
      const dataIdx = data.indexOf(row);
      mappingTable.push({
        pasteLine: i + 1,
        value: values[i],
        sortedIdx: targetSortedIdx,
        dataIdx: dataIdx,
        hero: row[nameCol]
      });
      if (dataIdx >= 0) {
        data[dataIdx][col] = values[i];
        recalcRow(data[dataIdx]);
      }
    } else {
      mappingTable.push({
        pasteLine: i + 1,
        value: values[i],
        sortedIdx: targetSortedIdx,
        dataIdx: 'NEW',
        hero: '(new row)'
      });
      const newRow = {};
      columns.forEach(c => { newRow[c] = computedFields[c] ? 0 : ''; });
      newRow[col] = values[i];
      data.push(newRow);
      recalcRow(newRow);
    }
  }
  console.table(mappingTable);

  // Verify: print data[] order (first 5 + last 2)
  console.log('data[] order after paste (original JSON order):');
  data.forEach((row, i) => {
    if (i < 5 || i >= data.length - 2) {
      console.log(`  data[${i}]  ${nameCol}=${row[nameCol]}  ${col}=${row[col]}`);
    } else if (i === 5) {
      console.log(`  ... (${data.length - 10} rows omitted) ...`);
    }
  });

  console.groupEnd();

  render();
  toast(`已粘贴 ${values.length} 个值到 "${col}" 列（详见控制台）`);
});

