// ── helpers ──
function $(id) { return document.getElementById(id); }

function toast(msg) {
  const el = Object.assign(document.createElement('div'), { className: 'toast', textContent: msg });
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 2000);
}

function detectColumns(arr) {
  if (!arr || !arr.length) return [];
  const keys = new Set();
  arr.forEach(obj => Object.keys(obj).forEach(k => keys.add(k)));
  return Array.from(keys);
}

function normalizeValue(val) {
  if (val === null || val === undefined) return '';
  if (typeof val === 'object') return JSON.stringify(val);
  return String(val);
}

// Check which computed fields apply to the current data
function resolveComputedFields() {
  computedFields = {};
  if (!data || !data.length) return;
  const cols = new Set(detectColumns(data));
  for (const [field, def] of Object.entries(COMPUTED_DEFS)) {
    if (cols.has(field) && def.dependsOn.every(d => cols.has(d))) {
      computedFields[field] = def;
    }
  }
}

// ── render ──
function render() {
  resolveComputedFields();

  if (!data || !data.length) {
    $('dataTable').style.display = 'none';
    $('empty').style.display = '';
    $('stats').style.display = 'none';
    $('saveBtn').disabled = true;
    $('addBtn').disabled = true;
    $('pasteBtn').disabled = true;
    return;
  }

  $('empty').style.display = 'none';
  $('dataTable').style.display = '';
  $('saveBtn').disabled = false;
  $('addBtn').disabled = false;
  $('pasteBtn').disabled = false;
  $('stats').style.display = 'flex';

  columns = detectColumns(data);

  // sort
  let sorted = [...data];
  if (sortKey && columns.includes(sortKey)) {
    sorted.sort((a, b) => {
      let va = a[sortKey], vb = b[sortKey];
      let na = parseFloat(va), nb = parseFloat(vb);
      if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
      return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
    });
  }

  // head
  let headHtml = '<tr><th class="col-index">#</th>';
  columns.forEach(col => {
    let cls = '';
    if (sortKey === col) cls = sortDir === 1 ? 'sort-asc' : 'sort-desc';
    if (computedFields[col]) cls += ' col-computed';
    const label = computedFields[col] ? col + ' 🔒' : col;
    headHtml += `<th class="${cls}" onclick="sortBy('${esc(col)}')">${label}<span class="sort-arrow">${sortKey === col ? (sortDir === 1 ? '▲' : '▼') : ''}</span></th>`;
  });
  headHtml += '<th class="col-index" style="cursor:default">✕</th></tr>';
  $('tableHead').innerHTML = headHtml;

  // body
  let bodyHtml = '';
  sorted.forEach((row, sortedIdx) => {
    const dataIdx = data.indexOf(row);
    bodyHtml += `<tr>`;
    bodyHtml += `<td class="col-index">${sortedIdx + 1}</td>`;
    columns.forEach(col => {
      if (computedFields[col]) {
        // ── computed cell (read-only) ──
        let val = normalizeValue(row[col]);
        bodyHtml += `<td class="computed">${val}</td>`;
      } else {
        // ── editable cell ──
        let val = normalizeValue(row[col]);
        let isMod = original && dataIdx >= 0 && dataIdx < original.length &&
          JSON.stringify(row) !== JSON.stringify(original[dataIdx]);
        bodyHtml += `<td class="editable${isMod ? ' modified' : ''}">`
          + `<input value="${val.replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}"`

