// ── edit ──
function startEdit(td) {
  const input = td.querySelector('input');
  if (!input || document.activeElement === input) return;
  input.focus();
}

function commitEdit(input) {
  if (!input.isConnected) return; // already detached (e.g. Tab navigation re-rendered)
  const col = input.dataset.col;
  const sortedIdx = parseInt(input.dataset.sortedIdx);
  let val = input.value.trim();

  // auto-detect number
  if (val !== '' && !isNaN(val) && !/^0\d/.test(val)) {
    val = Number(val);
  }

  if (!original) original = JSON.parse(JSON.stringify(data));

  // find the row in sorted view, then locate it in data[]
  const sorted = getSortedData();
  const row = sorted[sortedIdx];
  const dataIdx = data.indexOf(row);
  if (dataIdx < 0) return;

  data[dataIdx][col] = val;

  // recalc dependent computed fields
  recalcRow(data[dataIdx]);

  render();
}

// Recalculate all computed fields for a single row
function recalcRow(row) {
  for (const [field, def] of Object.entries(computedFields)) {
    row[field] = def.compute(row);
  }
}

// Recalculate all computed fields for all rows (e.g. after initial load)
function recalcAll() {
  if (!data) return;
  resolveComputedFields();
  data.forEach(row => recalcRow(row));
}

