// ── edit helpers ──
function startEdit(td) {
  const input = td.querySelector('input');
  if (!input || document.activeElement === input) return;
  input.focus();
}

// Mark an input (and its td) as dirty when the user types
function markDirty(input) {
  const td = input.closest('td');
  if (td) td.classList.add('modified');
  updateSaveState();
}

// Check if any input differs from its data-original value
function hasUnsavedChanges() {
  const inputs = $('tableBody').querySelectorAll('input');
  for (const inp of inputs) {
    if (inp.dataset.col && inp.value.trim() !== (inp.dataset.original || '')) return true;
  }
  return false;
}

// Enable/disable save-related UI based on dirty state
function updateSaveState() {
  const dirty = hasUnsavedChanges();
  $('applyBtn').disabled = !dirty;
  $('applyBtn').style.opacity = dirty ? '1' : '0.4';
}

// Read all inputs from DOM, write to data, recalc, re-render
function applyChanges() {
  if (!data) return;
  const inputs = $('tableBody').querySelectorAll('input');
  let changed = 0;

  if (!original) original = JSON.parse(JSON.stringify(data));

  const sorted = getSortedData();

  inputs.forEach(input => {
    const col = input.dataset.col;
    const sortedIdx = parseInt(input.dataset.sortedIdx);
    const newVal = input.value.trim();
    const oldVal = (input.dataset.original || '').trim();

    if (!col || newVal === oldVal) return;

    // auto-detect number
    let val = newVal;
    if (val !== '' && !isNaN(val) && !/^0\d/.test(val)) val = Number(val);

    // Map sortedIdx → data[]
    if (sortedIdx >= 0 && sortedIdx < sorted.length) {
      const row = sorted[sortedIdx];
      const dataIdx = data.indexOf(row);
      if (dataIdx >= 0) {
        data[dataIdx][col] = val;
        recalcRow(data[dataIdx]);
        changed++;
      }
    }
  });

  if (changed > 0) {
    recalcAll(); // ensure cross-row computed consistency
    render();
    toast(`已应用 ${changed} 个修改`);
  } else {
    toast('没有需要保存的修改');
  }
}

// Recalculate all computed fields for a single row
function recalcRow(row) {
  for (const [field, def] of Object.entries(computedFields)) {
    row[field] = def.compute(row);
  }
}

// Recalculate all computed fields for all rows (e.g. after initial load)
function recalcAll() {
  if (!data) return;
  resolveComputedFields();
  data.forEach(row => recalcRow(row));
}

