// ── Tab navigation: Tab/Shift+Tab moves between editable cells ──
$('tableBody').addEventListener('keydown', function (e) {
  if (e.key === 'Tab') {
    const input = document.activeElement;
    if (!input || input.tagName !== 'INPUT' || !input.dataset.col) return;
    e.preventDefault();

    // Record target before commitEdit destroys the DOM
    const td = input.closest('td');
    const allCells = [...$('tableBody').querySelectorAll('td.editable')];
    const idx = allCells.indexOf(td);
    const nextIdx = e.shiftKey ? idx - 1 : idx + 1;

    // Commit current edit (this calls render, rebuilding DOM)
    commitEdit(input);

    // Focus the next cell in the rebuilt DOM
    if (nextIdx >= 0) {
      const newCells = [...$('tableBody').querySelectorAll('td.editable')];
      if (nextIdx < newCells.length) startEdit(newCells[nextIdx]);
    }
  }

  // Enter on editable cell → move to cell below (same column, next row)
  if (e.key === 'Enter' && !e.shiftKey) {
    const input = document.activeElement;
    if (!input || input.tagName !== 'INPUT' || !input.dataset.col) return;
    e.preventDefault();

    const col = input.dataset.col;
    const sortedIdx = parseInt(input.dataset.sortedIdx);

