}

// ── render ──
function render() {
  resolveComputedFields();

  if (!data || !data.length) {
    $('dataTable').style.display = 'none';
    $('empty').style.display = '';
    $('stats').style.display = 'none';
    $('saveBtn').disabled = true;
    $('addBtn').disabled = true;
    $('pasteBtn').disabled = true;
    return;
  }

  $('empty').style.display = 'none';
  $('dataTable').style.display = '';
  $('saveBtn').disabled = false;
  $('addBtn').disabled = false;
  $('pasteBtn').disabled = false;
  $('stats').style.display = 'flex';

  columns = detectColumns(data);

  // sort
  let sorted = [...data];
  if (sortKey && columns.includes(sortKey)) {
    sorted.sort((a, b) => {
      let va = a[sortKey], vb = b[sortKey];
      let na = parseFloat(va), nb = parseFloat(vb);
      if (!isNaN(na) && !isNaN(nb)) return (na - nb) * sortDir;
      return String(va ?? '').localeCompare(String(vb ?? ''), 'zh-CN') * sortDir;
    });
  }

  // head
  let headHtml = '<tr><th class="col-index">#</th>';
  columns.forEach(col => {
    let cls = '';
    if (sortKey === col) cls = sortDir === 1 ? 'sort-asc' : 'sort-desc';
    if (computedFields[col]) cls += ' col-computed';
    const label = computedFields[col] ? col + ' 🔒' : col;
    headHtml += `<th class="${cls}" onclick="sortBy('${esc(col)}')">${label}<span class="sort-arrow">${sortKey === col ? (sortDir === 1 ? '▲' : '▼') : ''}</span></th>`;
  });

