file.content:
function countDirty() {
  if (!original) return 0;
  let count = 0;
  data.forEach((row, i) => {
    if (i >= original.length) {
      // new rows: count only non-computed fields
      columns.forEach(col => { if (!computedFields[col]) count++; });
      return;
    }
    columns.forEach(col => {
      if (computedFields[col]) return; // skip computed — they auto-update
      if (String(row[col] ?? '') !== String(original[i][col] ?? '')) count++;
    });
  });
  return count;
}

