file.content:
function deleteRow(sortedIdx) {
  const sorted = getSortedData();
  const row = sorted[sortedIdx];
  const dataIdx = data.indexOf(row);
  if (dataIdx < 0) return;
  if (!original) original = JSON.parse(JSON.stringify(data));
  const nameCol = columns.find(c => c.toLowerCase().includes('name') || c === 'heroName') || columns[0];
  const name = row[nameCol] || `第${dataIdx + 1}行`;
  if (!confirm(`确定要删除 "${name}" 吗？`)) return;
  data.splice(dataIdx, 1);
  render();
  toast(`已删除: ${name}`);
}

