function serveStatic(req, res, urlPath) {
  const rel = urlPath === '/' ? 'index.html' : decodeURIComponent(urlPath).replace(/^\/+/, '');
  const filePath = safeResolve(rel);
  if (!filePath) return sendText(res, 403, 'Forbidden');
