  laneCols.push({ label: "全局排名", field: "globalRank", type: "rank" });

  let html = `<div class="section-header">
    <h2>${laneName}</h2>
    <span class="count-badge">${heroes.length} 个英雄</span></div>`;
  html += renderStatCards(heroes);
  html += renderTable(sorted, laneCols, null);
  return html;
}

