      if (h.prevScore == null || h.score == null) return;
      const delta = h.score - h.prevScore;
      if (Math.abs(delta) < threshold) return;
      movers.push({ h, delta });
    } else {
      if (h.prevRank == null || h.rank == null) return;
      const delta = h.rank - h.prevRank;
      if (Math.abs(delta) < threshold) return;
      movers.push({ h, delta });
    }
  });
  if (!movers.length) return "";

  movers.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));

  // 名次：delta < 0 = 排名上升（变好）；delta > 0 = 排名下降（变差）
  // 梯度分：delta > 0 = 分数上升；delta < 0 = 分数下降
  const up = movers.filter(m => (useScore ? m.delta > 0 : m.delta < 0));
  const down = movers.filter(m => (useScore ? m.delta < 0 : m.delta > 0));

  const fmtDelta = d => (d >= 0 ? "▲" : "▼") + Math.abs(d).toFixed(useScore ? 1 : 0);
  const upCls = useScore ? "up" : "up";  // both use green for positive change
