    : (m.h.prevScore != null ? `分 ${m.h.prevScore.toFixed(1)}→${m.h.score.toFixed(1)}` : "");

  const chip = m => {
    const icon = m.h.headIcon
      ? `<img class="volatility-icon" src="${m.h.headIcon}" alt="" onerror="this.style.display='none'">`
      : "";
    const val = useScore
      ? `${m.h.prevScore != null ? m.h.prevScore.toFixed(1) : "?"}→${m.h.score != null ? m.h.score.toFixed(1) : "?"}`
      : `${m.h.prevRank}→${m.h.rank}`;
    const cls = (useScore ? m.delta > 0 : m.delta < 0) ? "up" : "down";
    return `<span class="volatility-chip ${cls}" title="${sub(m)}">${icon}<b>${m.h.name}</b><span class="volatility-val">${val}</span><em class="volatility-delta ${cls}">${fmtDelta(m.delta)}</em></span>`;
  };

  const metricName = useScore ? "梯度分" : "名次";

  let html = `<div class="volatility-banner">`;
