    html += `<div class="volatility-group">`;
    html += `<span class="volatility-group-label up">${useScore ? "▲ 分数上升" : "▲ 排名上升"}</span>`;
    html += `<div class="volatility-chips">${up.map(chip).join("")}</div></div>`;
  }
  if (down.length) {
    html += `<div class="volatility-group">`;
    html += `<span class="volatility-group-label down">${useScore ? "▼ 分数下降" : "▼ 排名下降"}</span>`;
    html += `<div class="volatility-chips">${down.map(chip).join("")}</div></div>`;
  }
  html += `</div>`;
  return html;
}

