input.old_string:
// 大幅波动横幅：最新一期 vs 上一期，名次变动 ≥ 阈值的英雄合并展示
const VOLATILITY_THRESHOLD = 10; // 名次波动达到该值以上进入横幅
function renderVolatilityBanner(heroes) {
  if (!gameConfig.hasDates) return "";
  const movers = heroes.filter(h =>
    h.prevRank != null && Math.abs(h.rank - h.prevRank) >= VOLATILITY_THRESHOLD
  );
  if (!movers.length) return "";
  movers.sort((a, b) => Math.abs(b.rank - b.prevRank) - Math.abs(a.rank - a.prevRank));

  const items = movers.map(h => {
    const delta = h.prevRank - h.rank; // 正 = 名次上升(数字变小)，负 = 下降
    const up = delta > 0;
    const cls = up ? "vol-up" : "vol-down";
    const arrow = up ? "▲" : "▼";
    const icon = h.headIcon
      ? `<img class="hero-icon" src="${h.headIcon}" alt="${h.name}" onerror="this.style.display='none'">`
      : "";
    const clickable = ` style="cursor:pointer" onclick="showHeroDetail('${h.name.replace(/'/g, "\\'")}')"`;
    return `<div class="vol-item ${cls}">
      ${icon}
      <span class="vol-name"${clickable}>${h.name}</span>
      <span class="vol-ranks">#${h.prevRank} → #${h.rank}</span>
      <span class="vol-delta">${arrow}${Math.abs(delta)}</span>
    </div>`;
  }).join("");

  return `<div class="volatility-banner">
    <div class="volatility-title">📊 大幅波动 <span class="volatility-count">${movers.length} 位英雄名次变动 ≥ ${VOLATILITY_THRESHOLD}</span></div>
    <div class="volatility-list">${items}</div>
  </div>`;
}

// ============================================================

