// 复刻 tierlist.js computeSG，验证横幅筛选逻辑
const fs = require('fs');
const dir = '曙光英雄';
const cfg = JSON.parse(fs.readFileSync(dir + '/config.json', 'utf8'));

function computeSG(rawData) {
  const heroes = rawData.map(h => ({
    name: h.heroName,
    headIcon: null,
    appearanceRank: parseInt(h.appearanceRank),
    combatPower: parseFloat(h.combatPower),
    winRate: parseFloat(String(h.winRate).replace('%', '')) / 100
  }));
  const N = heroes.length;
  const weights = cfg.algorithm.weights;
  const appearanceScores = heroes.map(h => 1 - (h.appearanceRank - 1) / (N - 1));
  const combatVals = heroes.map(h => h.combatPower);
  const combatMin = Math.min(...combatVals), combatMax = Math.max(...combatVals);
  const combatRange = combatMax - combatMin || 1;
  const combatScores = combatVals.map(v => (v - combatMin) / combatRange);
  const wrVals = heroes.map(h => h.winRate);
  const wrMin = Math.min(...wrVals), wrMax = Math.max(...wrVals);
  const wrRange = wrMax - wrMin || 1;
  const wrScores = wrVals.map(v => (v - wrMin) / wrRange);
  heroes.forEach((h, i) => {
    h.raw_weighted = weights.appearance * appearanceScores[i]
      + weights.combat * combatScores[i]
      + weights.winrate * wrScores[i];
  });
  const rawVals = heroes.map(h => h.raw_weighted);
  const rawMin = Math.min(...rawVals), rawMax = Math.max(...rawVals);
  const rawRange = rawMax - rawMin || 1;
  heroes.forEach(h => { h.score = ((h.raw_weighted - rawMin) / rawRange) * 100; });
  const sorted = [...heroes].sort((a, b) => b.score - a.score);
  sorted.forEach((h, i) => { h.rank = i + 1; });
  return { heroes, sorted };
}

const cur = computeSG(JSON.parse(fs.readFileSync(dir + '/曙光英雄_2026-08-02.json', 'utf8')));
const prev = computeSG(JSON.parse(fs.readFileSync(dir + '/曙光英雄_2026-07-20.json', 'utf8')));
const prevMap = new Map(prev.heroes.map(h => [h.name, h]));
cur.heroes.forEach(h => {
  const p = prevMap.get(h.name);
  if (p) { h.prevRank = p.rank; h.prevScore = p.score; }
});

const THRESHOLD = 10;
const movers = cur.heroes.filter(h => h.prevRank != null && Math.abs(h.rank - h.prevRank) >= THRESHOLD)
  .map(h => ({ name: h.name, prev: h.prevRank, now: h.rank, d: h.rank - h.prevRank, prevScore: h.prevScore, score: h.score }));
movers.sort((a, b) => Math.abs(b.d) - Math.abs(a.d));

console.log(`=== 名次波动 >= ${THRESHOLD} 的英雄（共 ${movers.length} 个）===\n`);
const up = movers.filter(m => m.d < 0);
const down = movers.filter(m => m.d > 0);
console.log(`[排名上升 ${up.length} 个]  (delta<0 = 名次数字变小 = 上升)`);
up.slice(0, 8).forEach(m => console.log(`  ▲ ${m.name.padEnd(6)} ${m.prev}→${m.now}  (d=${m.d})  分 ${m.prevScore.toFixed(1)}→${m.score.toFixed(1)}`));
if (up.length > 8) console.log(`  ... 等 ${up.length} 个`);
console.log(`\n[排名下降 ${down.length} 个]  (delta>0 = 名次数字变大 = 下降)`);
down.slice(0, 8).forEach(m => console.log(`  ▼ ${m.name.padEnd(6)} ${m.prev}→${m.now}  (d=+${m.d})  分 ${m.prevScore.toFixed(1)}→${m.score.toFixed(1)}`));
if (down.length > 8) console.log(`  ... 等 ${down.length} 个`);

// 附加：梯度分波动>=10 的（如果用户其实想按分数）
const scoreMovers = cur.heroes.filter(h => h.prevScore != null && Math.abs(h.score - h.prevScore) >= 10);
console.log(`\n=== 附: 梯度分(0~100)波动 >= 10 的英雄 ${scoreMovers.length} 个（对比用）===`);
scoreMovers.slice(0, 5).forEach(h => console.log(`  ${h.name}: ${h.prevScore.toFixed(1)}→${h.score.toFixed(1)} (d=${(h.score - h.prevScore).toFixed(1)})`));
EOF
