/* ============================================================
   英雄梯度排行榜 — 公共样式
   适配 LOLM 和 曙光英雄，深色主题，响应式
   ============================================================ */

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
                 "Microsoft YaHei", sans-serif;
    background: #0d1117;
    color: #c9d1d9;
    min-height: 100vh;
}

/* ---- 头部 ---- */
.header {
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    padding: 24px 24px 20px;
    text-align: center;
    border-bottom: 1px solid #30363d;
}
.header h1 { font-size: 1.8rem; color: #f0f6fc; margin-bottom: 4px; }
.header .subtitle {
    font-size: 0.85rem; color: #8b949e; margin-top: 4px;
}

/* ---- 游戏选择器 ---- */
.game-selector {
    display: flex; justify-content: center; gap: 8px;
    margin-top: 16px; flex-wrap: wrap;
}
.game-selector button {
    background: rgba(255,255,255,0.06);
    color: #8b949e; border: 1px solid #30363d;
    padding: 10px 28px; border-radius: 8px; cursor: pointer;
    font-size: 0.95rem; transition: all 0.25s;
    display: flex; align-items: center; gap: 8px;
}
.game-selector button:hover {
    background: rgba(255,255,255,0.10); color: #c9d1d9;
    border-color: #484f58;
}
.game-selector button.active {
    background: #1f6feb; border-color: #1f6feb; color: #fff;
    box-shadow: 0 0 12px rgba(31,111,235,0.3);
}
.game-selector .game-badge {
    font-size: 0.7rem; background: rgba(255,255,255,0.15);
    padding: 1px 6px; border-radius: 3px;
}

/* ---- 导航栏 ---- */
.nav {
    display: flex; justify-content: center; gap: 4px;
    padding: 12px 24px; background: #161b22;
    border-bottom: 1px solid #30363d; position: sticky; top: 0; z-index: 100;
    flex-wrap: wrap;
}
.nav button {
    background: #21262d; color: #c9d1d9; border: 1px solid #30363d;
    padding: 7px 18px; border-radius: 6px; cursor: pointer;
    font-size: 0.88rem; transition: all 0.2s;
}
.nav button:hover { background: #30363d; }
.nav button.active { background: #1f6feb; border-color: #1f6feb; color: #fff; }
.nav .hero-count { color: #8b949e; font-size: 0.8rem; align-self: center; margin-left: 8px; }

/* ---- 控制栏 ---- */
.controls {
    display: flex; justify-content: center; align-items: center; gap: 16px;
    padding: 12px 24px; flex-wrap: wrap;
}
.controls .label { color: #8b949e; font-size: 0.8rem; margin-right: 2px; }
.controls button {
    background: transparent; color: #8b949e; border: 1px solid #30363d;
    padding: 5px 14px; border-radius: 4px; cursor: pointer; font-size: 0.8rem;
    transition: all 0.2s;
}
.controls button:hover { border-color: #484f58; color: #c9d1d9; }
.controls button.active { background: #238636; border-color: #238636; color: #fff; }

/* ---- 内容区 ---- */
.container { max-width: 1600px; margin: 0 auto; padding: 24px; }

.section-header {
    display: flex; align-items: center; gap: 12px;
    margin-bottom: 20px; padding-bottom: 12px; border-bottom: 1px solid #30363d;
    flex-wrap: wrap;
}
.section-header h2 { font-size: 1.5rem; color: #f0f6fc; }
.section-header .count-badge {
    color: #8b949e; font-size: 0.9rem; background: #21262d;
    padding: 2px 10px; border-radius: 10px;
}
.section-header .hint {
    color: #8b949e; font-size: 0.85rem; margin-left: auto;
}

/* ---- 统计卡片 ---- */
.stats-row { display: flex; gap: 12px; margin-bottom: 20px; flex-wrap: wrap; }
.stat-card {
    background: #161b22; border: 1px solid #30363d; border-radius: 8px;
    padding: 12px 16px; flex: 1; min-width: 100px; text-align: center;
}
.stat-card .stat-value { font-size: 1.4rem; font-weight: 700; color: #f0f6fc; }
.stat-card .stat-label { font-size: 0.75rem; color: #8b949e; margin-top: 2px; }

/* ---- 表格 ---- */
.table-wrapper { overflow-x: auto; border-radius: 8px; border: 1px solid #30363d; }
table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
thead th {
    background: #161b22; color: #8b949e; padding: 12px 14px;
    text-align: left; font-weight: 600; border-bottom: 1px solid #30363d;
    white-space: nowrap; position: sticky; top: 0; cursor: pointer; user-select: none;
}
thead th:hover { color: #f0f6fc; }
thead th .sort-icon { opacity: 0.3; margin-left: 4px; }
thead th.sorted .sort-icon { opacity: 1; }
tbody td { padding: 10px 14px; border-bottom: 1px solid #21262d; }
tbody tr:hover { background: rgba(255,255,255,0.03); }
tbody tr.current-highlight { background: rgba(31,111,235,0.08); }

/* ---- 排名数字 ---- */
.rank-num { font-weight: 700; font-size: 1rem; color: #f0f6fc; text-align: center; }
.rank-1 { color: #ffd700; font-size: 1.3rem; }
.rank-2 { color: #c0c0c0; font-size: 1.2rem; }
.rank-3 { color: #cd7f32; font-size: 1.1rem; }

/* ---- 梯度标签 ---- */
.tier-badge {
    display: inline-block; padding: 3px 10px; border-radius: 4px;
    font-weight: 700; font-size: 0.8rem; color: #fff; text-align: center; min-width: 44px;
}

/* ---- 分数条 ---- */
.score-bar-wrap { display: flex; align-items: center; gap: 8px; min-width: 120px; }
.score-bar { flex: 1; height: 6px; background: #21262d; border-radius: 3px; overflow: hidden; }
.score-bar-fill { height: 100%; border-radius: 3px; transition: width 0.3s; }
.score-value { font-weight: 600; font-size: 0.85rem; color: #f0f6fc; min-width: 44px; text-align: right; }

/* ---- 英雄名 + 头像 ---- */
.hero-name { font-weight: 600; color: #f0f6fc; }
.hero-cell { display: flex; align-items: center; gap: 8px; }
.hero-icon {
    width: 32px; height: 32px; border-radius: 50%;
    border: 1.5px solid #30363d; object-fit: cover;
    background: #21262d; flex-shrink: 0;
}

/* ---- 高亮色 ---- */
.wr-high { color: #3fb950; font-weight: 600; }
.wr-mid { color: #d29922; }
.wr-low { color: #f85149; }
.cw-high { color: #3fb950; font-weight: 600; }
.cw-mid { color: #d29922; }
.cw-low { color: #f85149; }

/* ---- 搜索框 ---- */
.search-box {
    background: #21262d; border: 1px solid #30363d; border-radius: 6px;
    padding: 8px 14px; color: #c9d1d9; font-size: 0.9rem; width: 200px;
    outline: none; transition: border-color 0.2s;
}
.search-box:focus { border-color: #1f6feb; }
.search-box::placeholder { color: #484f58; }

/* ---- 页脚 ---- */
.footer {
    text-align: center; padding: 24px; color: #484f58;
    font-size: 0.8rem; border-top: 1px solid #30363d; margin-top: 24px;
}

/* ---- 梯度网格视图 ---- */
.tier-grid {
    display: flex; flex-direction: column;
    gap: 2px; background: #000; padding: 2px;
    border-radius: 8px; overflow: hidden;
    border: 1px solid #30363d; min-width: 320px;
}
.tier-row {
    display: flex; flex-direction: row; min-height: 84px;
    background: #161b22;
}
.tier-label {
    display: flex; align-items: center; justify-content: center;
    width: 96px; min-width: 96px; font-weight: 800; font-size: 1.1rem;
    color: #fff; text-shadow: 0 1px 3px rgba(0,0,0,0.5);
    letter-spacing: 1px; user-select: none;
}
.tier-icons {
    display: flex; flex-wrap: wrap; gap: 2px;
    padding: 2px; align-items: center; flex: 1;
    background: #0d1117;
}

.tier-hero {
    cursor: pointer; transition: transform 0.15s, filter 0.15s;
    width: 80px; flex-shrink: 0;
}
.tier-hero:hover {
    transform: scale(1.12); filter: brightness(1.15);
}
.tier-hero-img-wrap {
    position: relative; width: 80px; height: 80px;
    overflow: hidden; border-radius: 2px;
}
.tier-hero img {
    width: 80px; height: 80px;
    object-fit: cover; display: block;
    background: #21262d;
}
.tier-hero .tier-hero-name {
    position: absolute; bottom: 0; left: 0; right: 0;
    background: rgba(0, 0, 0, 0.6);
    color: #e6e6e6; font-size: 10px; text-align: center;
    padding: 2px 4px; line-height: 1.2;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    pointer-events: none;
}
.tier-hero:hover .tier-hero-name { background: rgba(0, 0, 0, 0.78); color: #fff; }

/* ---- 网格视图空行 ---- */
.tier-row-empty .tier-icons {
    color: #484f58; font-size: 0.8rem; font-style: italic;
    justify-content: flex-start; padding-left: 16px;
}

/* ---- 响应式：网格视图 ---- */
@media (max-width: 768px) {
    .tier-label { width: 48px; min-width: 48px; font-size: 0.75rem; }
    .tier-icons { gap: 2px; padding: 2px; }
    .tier-hero { width: 48px; }
    .tier-hero-img-wrap { width: 48px; height: 48px; }
    .tier-hero img { width: 48px; height: 48px; }
    .tier-hero .tier-hero-name { font-size: 7px; padding: 1px 2px; }
    .tier-row { min-height: 52px; }
}

/* ---- 大幅波动横幅（曙光英雄表格页） ---- */
.volatility-banner {
    background: linear-gradient(135deg, #16213e 0%, #1a1a2e 100%);
    border: 1px solid #30363d;
    border-radius: 8px;
    padding: 14px 18px;
    margin-bottom: 20px;
}
.volatility-head {
    display: flex; align-items: center; gap: 10px;
    margin-bottom: 10px; flex-wrap: wrap;
}
.volatility-title { font-weight: 700; color: #f0f6fc; font-size: 0.95rem; }
.volatility-count {
    background: #1f6feb; color: #fff; border-radius: 10px;
    padding: 1px 8px; font-size: 0.78rem; font-weight: 600;
}
.volatility-note { color: #8b949e; font-size: 0.78rem; }
.volatility-group {
    display: flex; align-items: flex-start; gap: 10px;
    margin-bottom: 6px; flex-wrap: wrap;
}
.volatility-group:last-child { margin-bottom: 0; }
.volatility-group-label {
    font-size: 0.78rem; font-weight: 600; padding: 4px 10px;
    border-radius: 4px; white-space: nowrap;
}
.volatility-group-label.up { background: rgba(63,185,80,0.15); color: #3fb950; }
.volatility-group-label.down { background: rgba(248,81,73,0.15); color: #f85149; }
.volatility-chips { display: flex; flex-wrap: wrap; gap: 8px; flex: 1; }
.volatility-chip {
    display: inline-flex; align-items: center; gap: 6px;
    background: #21262d; border: 1px solid #30363d; border-radius: 6px;
    padding: 4px 10px; font-size: 0.82rem; cursor: default;
}
.volatility-chip:hover { border-color: #484f58; }
.volatility-chip b { color: #f0f6fc; font-weight: 600; }
.volatility-val { color: #8b949e; font-size: 0.78rem; }
.volatility-delta { font-weight: 700; font-style: normal; }
.volatility-delta.up { color: #3fb950; }
.volatility-delta.down { color: #f85149; }
.volatility-icon {
    width: 24px; height: 24px; border-radius: 50%;
    object-fit: cover; background: #161b22; flex-shrink: 0;
}

/* ---- 无分路提示 ---- */
.no-lanes-notice {
    text-align: center; padding: 16px 24px; background: #161b22;
    border-bottom: 1px solid #30363d; color: #8b949e; font-size: 0.85rem;
}

/* ---- HeroDetail 覆盖层 ---- */
.hero-detail-overlay {
    display: none; position: fixed; inset: 0; z-index: 1000;
    background: rgba(0,0,0,0.7); align-items: center; justify-content: center;
}
.hero-detail-panel {
    background: #0d1117; border: 1px solid #30363d; border-radius: 12px;
    width: 90vw; max-width: 1000px; max-height: 90vh; overflow-y: auto;
    box-shadow: 0 8px 32px rgba(0,0,0,0.5);
}
.hero-detail-header {
    display: flex; align-items: center; gap: 16px;
    padding: 16px 20px; border-bottom: 1px solid #30363d;
    position: sticky; top: 0; background: #0d1117; z-index: 1;
}
.hero-detail-title { font-size: 1.1rem; font-weight: 600; flex: 1; }
.hero-detail-close {
    padding: 6px 14px; border: 1px solid #f85149; border-radius: 6px;
    background: transparent; color: #f85149; cursor: pointer;
    font-size: 14px; font-family: inherit;
}
.hero-detail-close:hover { background: rgba(248,81,73,0.15); }
.hero-detail-body { padding: 20px; }
.hero-detail-body .chart-box {
    background: #161b22; border: 1px solid #30363d;
    border-radius: 8px; padding: 16px; margin-bottom: 16px;
}
/* mini-table for hero detail */
.hero-detail-body .mini-table {
    width: 100%; border-collapse: collapse; font-size: 0.82rem;
}
.hero-detail-body .mini-table th,
.hero-detail-body .mini-table td {
    padding: 8px 12px; text-align: center; border: 1px solid #21262d;
}
.hero-detail-body .mini-table th { background: #161b22; color: #8b949e; font-weight: 600; }
.hero-detail-body .mini-table td { background: #0d1117; }

/* In grid/table, make hero names hint they're clickable */
.hero-detail-body .hero-cell[style*="cursor:pointer"]:hover { opacity: 0.8; }

/* ---- 响应式 ---- */
@media (max-width: 768px) {
    .header h1 { font-size: 1.3rem; }
    .header { padding: 20px 16px 16px; }
    .game-selector button { padding: 8px 16px; font-size: 0.85rem; }
    .nav button { padding: 6px 12px; font-size: 0.78rem; }
    table { font-size: 0.75rem; }
    thead th { padding: 8px 10px; }
    tbody td { padding: 8px 10px; }
    .stats-row { gap: 6px; }
    .stat-card { padding: 8px 10px; }
    .stat-card .stat-value { font-size: 1.1rem; }
    .controls { gap: 8px; }
    .controls button { padding: 4px 8px; font-size: 0.7rem; }
    .search-box { width: 140px; font-size: 0.8rem; }
    .container { padding: 12px; }
    .score-bar-wrap { min-width: 80px; }
    .score-value { font-size: 0.75rem; min-width: 32px; }
    .section-header h2 { font-size: 1.2rem; }
}

#!/usr/bin/env node
// ============================================================
// server.js — 零依赖 Node 本地服务器
//
// 用法:  node server.js [端口]      (默认 3000)
// 打开:  http://127.0.0.1:3000/        站点
//        http://127.0.0.1:3000/editor.html   数据编辑器
//
// 功能:
//   1. 静态托管项目文件（替代 Live Server）
//   2. GET  /api/games              — 自动发现含 config.json 的游戏目录
//   3. GET  /api/{dir}/config       — 返回配置；日期类游戏自动扫描最新数据文件
//   4. GET  /api/{dir}/list         — 列出目录下可用数据文件
//   5. POST /api/{dir}/save         — 把编辑结果原子写回磁盘
//   6. GET  /api/watch              — SSE 文件监听，数据变化实时推送（前端自动刷新）
//
// 安全: 只绑定 127.0.0.1；所有文件操作带路径穿越防护；保存接口校验文件名。
// ============================================================
"use strict";

const http = require("http");
const fs = require("fs");
const path = require("path");

const ROOT = __dirname;
const PORT = Number(process.env.PORT) || Number(process.argv[2]) || 3000;
const HOST = "127.0.0.1";
const MAX_BODY = 64 * 1024 * 1024; // 保存请求体上限 64MB

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".webp": "image/webp",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".md": "text/markdown; charset=utf-8",
  ".txt": "text/plain; charset=utf-8"
};

// 日期数据文件名：`游戏名_YYYY-MM-DD.json`（如 曙光英雄_2026-08-02.json）
const DATE_RE = /^(.+?)_(\d{4}-\d{2}-\d{2})\.json$/;
const SAFE_DIR_RE = /^[\w一-龥-]+$/;
const SAFE_FILE_RE = /^[\w一-龥-]+\.json$/;

// ---------- 基础工具 ----------
function sendJSON(res, code, obj) {
  const body = JSON.stringify(obj, null, 2);
  res.writeHead(code, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store"
  });
  res.end(body);
}

function sendText(res, code, text, type = "text/plain; charset=utf-8") {
  res.writeHead(code, { "Content-Type": type, "Cache-Control": "no-store" });
  res.end(text);
}

// 防路径穿越：把相对路径安全地解析到 ROOT 之内，否则返回 null
function safeResolve(rel) {
  const clean = String(rel).replace(/\\/g, "/").replace(/^\/+/, "");
  if (!clean) return null;
  const abs = path.resolve(ROOT, clean);
  if (abs !== ROOT && !abs.startsWith(ROOT + path.sep)) return null;
  return abs;
}

function readBody(req, cb) {
  let size = 0;
  const chunks = [];
  req.on("data", c => {
    size += c.length;
    if (size > MAX_BODY) {
      cb(null, new Error("请求体过大"));
      req.destroy();
      return;
    }
    chunks.push(c);
  });
  req.on("end", () => cb(Buffer.concat(chunks)));
  req.on("error", e => cb(null, e));
}

// ---------- 数据发现 ----------
function discoverGames() {
  const games = [];
  let entries;
  try { entries = fs.readdirSync(ROOT, { withFileTypes: true }); }
  catch { return games; }
  for (const e of entries) {
    if (!e.isDirectory()) continue;
    const cfgPath = path.join(ROOT, e.name, "config.json");
    if (!fs.existsSync(cfgPath)) continue;
    try {
      const cfg = JSON.parse(fs.readFileSync(cfgPath, "utf8"));
      games.push({
        dir: e.name,
        gameId: cfg.gameId || e.name,
        gameName: cfg.gameName || e.name,
        gameIcon: cfg.gameIcon || "🎮",
        hasLanes: !!cfg.hasLanes,
        hasDates: !!cfg.hasDates
      });
    } catch { /* 忽略损坏的 config */ }
  }
  return games;
}

function isValidDir(dir) {
  return SAFE_DIR_RE.test(dir) && fs.existsSync(path.join(ROOT, dir, "config.json"));
}

// 扫描目录里所有 `*_YYYY-MM-DD.json`，按日期升序（最新在最后）
function scanDates(dir) {
  const dirPath = path.join(ROOT, dir);
  const dates = [];
  let files;
  try { files = fs.readdirSync(dirPath, { withFileTypes: true }); }
  catch { return dates; }
  for (const f of files) {
    if (!f.isFile()) continue;
    const m = DATE_RE.exec(f.name);
    if (m) dates.push({ date: m[2], file: f.name });
  }
  dates.sort((a, b) => a.date.localeCompare(b.date));
  return dates;
}

// 读取配置；日期类游戏把 dates 换成磁盘扫描结果，defaultDate 始终指向最新
function getConfig(dir) {
  const cfg = JSON.parse(fs.readFileSync(path.join(ROOT, dir, "config.json"), "utf8"));
  if (cfg.hasDates) {
    const dates = scanDates(dir);
    if (dates.length) {
      cfg.dates = dates;
      cfg.defaultDate = dates[dates.length - 1].date; // 自动指向最新
    }
  }
  return cfg;
}

function listFiles(dir) {
  const dirPath = path.join(ROOT, dir);
  const files = fs.readdirSync(dirPath, { withFileTypes: true })
    .filter(f => f.isFile() && f.name.endsWith(".json") && f.name !== "config.json")
    .map(f => f.name)
    .sort();
  return { dir, files };
}

// ---------- 保存 ----------
function handleSave(dir, body, res) {
  let payload;
  try { payload = JSON.parse(body); }
  catch { return sendJSON(res, 400, { ok: false, error: "请求体不是合法 JSON" }); }

  const file = String(payload.file || "");
  if (!SAFE_FILE_RE.test(file)) {
    return sendJSON(res, 400, { ok: false, error: "非法文件名: " + file });
  }
  const data = payload.data;
  if (data === undefined || data === null || typeof data !== "object") {
    return sendJSON(res, 400, { ok: false, error: "data 必须是对象或数组" });
  }

  const filePath = safeResolve(path.join(dir, file));
  if (!filePath || !filePath.startsWith(path.join(ROOT, dir) + path.sep)) {
    return sendJSON(res, 403, { ok: false, error: "路径越界" });
  }

  const json = JSON.stringify(data, null, 2);
  const tmp = filePath + ".tmp";
  try {
    fs.writeFileSync(tmp, json, "utf8");
    fs.renameSync(tmp, filePath); // 原子替换，避免写一半损坏
  } catch (e) {
    try { fs.unlinkSync(tmp); } catch {}
    return sendJSON(res, 500, { ok: false, error: "写入失败: " + e.message });
  }
  const st = fs.statSync(filePath);
  sendJSON(res, 200, {
    ok: true,
    file,
    size: st.size,
    rows: Array.isArray(data) ? data.length : Object.keys(data).length,
    mtime: st.mtime.toISOString()
  });
}

// ---------- 文件监听 / SSE ----------
const watchClients = new Set();
const watchTimers = new Map();

function notifyChange(dir, file) {
  const msg = JSON.stringify({ dir, file, event: "change", ts: Date.now() });
  watchClients.forEach(c => { try { c.write(`data: ${msg}\n\n`); } catch {} });
}

function setupWatchers() {
  for (const g of discoverGames()) {
    const dirPath = path.join(ROOT, g.dir);
    try {
      fs.watch(dirPath, (event, filename) => {
        const name = filename ? String(filename) : "";
        if (!name || name.endsWith(".tmp")) return;
        clearTimeout(watchTimers.get(g.dir));
        watchTimers.set(g.dir, setTimeout(() => notifyChange(g.dir, name), 300));
      });
    } catch { /* 忽略无法监听的目录 */ }
  }
}

function handleWatch(req, res) {
  res.writeHead(200, {
    "Content-Type": "text/event-stream; charset=utf-8",
    "Cache-Control": "no-cache",
    "Connection": "keep-alive"
  });
  res.write(": connected\n\n");
  watchClients.add(res);
  const cleanup = () => watchClients.delete(res);
  req.on("close", cleanup);
  res.on("close", cleanup);
  // 心跳，防止空闲连接被断开
  const hb = setInterval(() => { try { res.write(": ping\n\n"); } catch {} }, 25000);
  res.on("close", () => clearInterval(hb));
}

// ---------- API 路由 ----------
function handleApi(req, res, pathname, method) {
  const segs = pathname.split("/").filter(Boolean).map(s => {
    try { return decodeURIComponent(s); } catch { return s; }
  });
  // segs[0] === "api"

  if (segs.length === 2 && segs[1] === "games") {
    return sendJSON(res, 200, { games: discoverGames() });
  }
  if (segs.length === 2 && segs[1] === "watch") {
    return handleWatch(req, res);
  }
  if (segs.length === 3) {
    const dir = segs[1];
    const action = segs[2];
    if (!isValidDir(dir)) return sendJSON(res, 404, { error: "未知游戏目录: " + dir });
    try {
      if (method === "GET" && action === "config") return sendJSON(res, 200, getConfig(dir));
      if (method === "GET" && action === "list") return sendJSON(res, 200, listFiles(dir));
      if (method === "POST" && action === "save") {
        return readBody(req, (body, err) => {
          if (err) return sendJSON(res, 400, { ok: false, error: err.message });
          handleSave(dir, body, res);
        });
      }
    } catch (e) {
      return sendJSON(res, 500, { error: e.message });
    }
    return sendJSON(res, 404, { error: "未知操作: " + action });
  }
  return sendJSON(res, 404, { error: "接口不存在" });
}

// ---------- 静态服务 ----------
function serveStatic(req, res, pathname) {
  let rel;
  try { rel = decodeURIComponent(pathname); } catch { return sendText(res, 400, "Bad Request"); }
  if (rel === "/") rel = "index.html";
  const filePath = safeResolve(rel);
  if (!filePath) return sendText(res, 403, "Forbidden");
  fs.stat(filePath, (err, st) => {
    if (err || !st.isFile()) return sendText(res, 404, "Not Found");
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, {
      "Content-Type": MIME[ext] || "application/octet-stream",
      "Cache-Control": "no-cache"
    });
    fs.createReadStream(filePath).pipe(res);
  });
}

// ---------- 启动 ----------
const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://" + (req.headers.host || "localhost"));
  const pathname = url.pathname;

  if (pathname === "/api" || pathname === "/api/") {
    return sendJSON(res, 200, {
      endpoints: ["/api/games", "/api/{dir}/config", "/api/{dir}/list", "/api/{dir}/save", "/api/watch"]
    });
  }
  if (pathname.startsWith("/api/")) return handleApi(req, res, pathname, req.method);
  if (req.method !== "GET") return sendText(res, 405, "Method Not Allowed");
  serveStatic(req, res, pathname);
});

setupWatchers();

server.listen(PORT, HOST, () => {
  console.log("\n  MOBA 梯度数据服务器已启动");
  console.log(`  → 站点:   http://${HOST}:${PORT}/`);
  console.log(`  → 编辑器: http://${HOST}:${PORT}/editor.html`);
  console.log(`  → API:    http://${HOST}:${PORT}/api/games`);
  console.log("");
  const games = discoverGames();
  if (!games.length) console.log("  （未发现含 config.json 的游戏目录）");
  games.forEach(g => {
    const extra = g.hasDates ? "（日期自动扫描）" : g.hasLanes ? "（分路模式）" : "";
    console.log(`  📁 ${g.gameName}  ${extra}`);
  });
  console.log("");
});

