function loadFile(input) {
  const file = input.files[0];
  if (!file) return;
  currentFile = file.name;
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const parsed = JSON.parse(reader.result);
      setData(parsed, file.name);
    } catch (e) {
      alert('JSON 解析失败: ' + e.message);
    }
  };
  reader.readAsText(file);
  input.value = '';
}

function loadPreset(path) {
  if (!path) return;
  $('presetSelect').value = '';
  fetch(path)
    .then(r => { if (!r.ok) throw new Error(r.status + ' ' + r.statusText); return r.json(); })
    .then(json => {
      currentFile = path.split('/').pop();
      setData(json, currentFile);
    })
    .catch(err => alert('加载失败: ' + err.message));
}

// ── save ──
async function saveJSON() {
  if (!data) return;

  // Final recalculation before saving to ensure all computed values are correct
  recalcAll();

  const json = JSON.stringify(data, null, 2);

  if (currentFileHandle) {
    // Direct write-back to the file that was opened (no download dialog)
    try {
      const writable = await currentFileHandle.createWritable();
      await writable.write(json);
      await writable.close();
      toast(`已保存到 ${currentFile || '文件'}`);
    } catch (e) {
      alert('直接保存失败: ' + e.message + '\n将使用下载方式保存。');
      downloadJSON(json);
    }
  } else if ('showSaveFilePicker' in window) {
    // No handle yet → ask user to pick a save location once, then remember it
    try {
      currentFileHandle = await window.showSaveFilePicker({
        suggestedName: currentFile || 'data.json',
        types: [{ description: 'JSON files', accept: { 'application/json': ['.json'] } }]
      });
      const writable = await currentFileHandle.createWritable();
      await writable.write(json);
      await writable.close();
      toast(`已保存到 ${currentFile || '文件'}（后续 Ctrl+S 将直接写回此位置）`);
    } catch (e) {
      if (e.name === 'AbortError') {
        downloadJSON(json);  // user cancelled — fall back to download
      } else {
        alert('保存失败: ' + e.message + '\n将使用下载方式保存。');
        downloadJSON(json);
      }
    }
  } else {
    // File System Access API not available → download
    downloadJSON(json);
  }
}

function downloadJSON(json) {
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement('a'), {
    href: url,
    download: currentFile || 'data.json'
  });
  a.click();
  URL.revokeObjectURL(url);
  toast('JSON 已下载（含自动计算值）');
}

