// js/dataSource.js — 数据访问层：优先走 Node 服务器 API，无服务器时回退到直接 fetch
const DataSource = (() => {
  let serverReady = null; // 缓存探测结果
  async function probe() {
    if (serverReady === null) {
      try {
        const r = await fetch('/api/games');
        serverReady = r.ok;
      } catch { serverReady = false; }
    }
    return serverReady;
  }
  async function fetchJSON(url, options) {
    const r = await fetch(url, options);
    if (!r.ok) throw new Error(r.status + ' ' + r.statusText);
    return r.json();
  }
  return {
    isServerReady: probe,
    // 读取游戏配置：优先 API（自动扫最新日期），回退到直接读 config.json
    async loadConfig(dir) {
      if (await probe()) {
        try { return await fetchJSON('/api/' + encodeURIComponent(dir) + '/config'); } catch { /* fall through */ }
      }
      return fetchJSON(dir + '/config.json');
    },
    // 保存：优先 POST 到服务器写回磁盘，回退到 null（调用方改用下载）
