        const r = await fetch('/api/' + encodeURIComponent(dir) + '/save', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ file, data })
        });
        if (!r.ok) throw new Error(r.status + ' ' + r.statusText);
        return await r.json();
      } catch { return null; }
