  req.on("close", cleanup);
  res.on("close", cleanup);
  // 心跳，防止空闲连接被断开
  const hb = setInterval(() => { try { res.write(": ping\n\n"); } catch {} }, 25000);
  res.on("close", () => clearInterval(hb));
