const fs = require("fs");
const path = require("path");
const dir = "曙光英雄";
const files = fs.readdirSync(dir).filter(f => /^.+?_\d{4}-\d{2}-\d{2}\.json$/.test(f)).sort();
console.log("data files:", files);

function computeSG(list) {
  const W = { appearance: 0.20, combat: 0.50, winrate: 0.30 };
  const f = h => h.appearance * W.appearance + h.combat * W.combat + h.winrate * W.winrate;
  const raw = list.map(h => ({ h, s: f(h) }));
  const vals = raw.map(x => x.s);
  const min = Math.min(...vals), max = Math.max(...vals);
  const norm = raw.map(x => ({ h: x.h, s: max === min ? 50 : (x.s - min) / (max - min) * 100 }));
  norm.sort((a, b) => b.s - a.s);
  return norm.map((x, i) => ({ name: x.h.name, rank: i + 1, score: x.s }));
}

const a = JSON.parse(fs.readFileSync(path.join(dir, files[files.length - 2]), "utf8"));
const b = JSON.parse(fs.readFileSync(path.join(dir, files[files.length - 1]), "utf8"));
const A = computeSG(Array.isArray(a) ? a : a.heroes || a.list || []);
const B = computeSG(Array.isArray(b) ? b : b.heroes || b.list || []);
const mapA = new Map(A.map(x => [x.name, x]));
let count = 0;
B.forEach(x => {
  const p = mapA.get(x.name);
  if (p) {
    const d = x.rank - p.rank;
    if (Math.abs(d) >= 10) { count++; console.log(`  ${x.name}: #${p.rank} → #${x.rank}  (Δ=${d})`); }
  }
});
console.log("movers ≥10:", count, "/", B.length);
'

